[CmdletBinding(SupportsShouldProcess)]
param([Parameter(Mandatory)][string]$ShareName,[Parameter(Mandatory)][string]$Department,[string]$Root='D:\Shares')
$ErrorActionPreference='Stop';Import-Module ActiveDirectory
$path=Join-Path $Root $ShareName;$read="DL-FS01-$($ShareName)-R";$modify="DL-FS01-$($ShareName)-RW"
foreach($group in $read,$modify){if(-not(Get-ADGroup -Filter "SamAccountName -eq '$group'")){if($PSCmdlet.ShouldProcess($group,'Create domain local access group')){New-ADGroup -Name $group -SamAccountName $group -GroupScope DomainLocal -GroupCategory Security -Path 'OU=Groups,OU=CTS,DC=cts-lab,DC=local'}}}
if($PSCmdlet.ShouldProcess($path,'Create secured SMB share')){New-Item $path -ItemType Directory -Force|Out-Null;$acl=Get-Acl $path;$acl.SetAccessRuleProtection($true,$false);$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule('SYSTEM','FullControl','ContainerInherit,ObjectInherit','None','Allow')));$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule('CTS-LAB\Domain Admins','FullControl','ContainerInherit,ObjectInherit','None','Allow')));$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule("CTS-LAB\$modify",'Modify','ContainerInherit,ObjectInherit','None','Allow')));$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule("CTS-LAB\$read",'ReadAndExecute','ContainerInherit,ObjectInherit','None','Allow')));Set-Acl $path $acl;New-SmbShare -Name $ShareName -Path $path -FullAccess 'CTS-LAB\Domain Admins' -ChangeAccess "CTS-LAB\$modify" -ReadAccess "CTS-LAB\$read"|Out-Null}
[pscustomobject]@{Share=$ShareName;Path=$path;Department=$Department;ReadGroup=$read;ModifyGroup=$modify}
